// مسیر «تغییر وضعیت»: پورتال فهرست اعلان‌ها (یک مورد برای هر گیرنده) را فرستاده است.
const req = $input.first().json;
if (!$env.AGENT_TOKEN || (req.headers || {})['x-agent-token'] !== $env.AGENT_TOKEN) {
  throw new Error('Unauthorized: invalid X-Agent-Token');
}
const notifications = (req.body || {}).notifications;
return (Array.isArray(notifications) ? notifications : []).map((n) => ({ json: n }));

// مسیر «اجرای دستی یادآوری‌ها» (دستور run_reminders پورتال): بررسی توکن و تاریخ شبیه‌سازی‌شده.
const req = $input.first().json;
if (!$env.AGENT_TOKEN || (req.headers || {})['x-agent-token'] !== $env.AGENT_TOKEN) {
  throw new Error('Unauthorized: invalid X-Agent-Token');
}
const today = String((req.body || {}).today || '');
if (today && !/^\d{4}-\d{2}-\d{2}$/.test(today)) throw new Error('today must be YYYY-MM-DD');
return [{ json: { today } }];

// مسیر «یادآوری مهلت»: پورتال با قواعد قطعی گفته امروز چه یادآوری‌هایی سررسید شده است.
const notifications = $input.first().json.notifications;
return (Array.isArray(notifications) ? notifications : []).map((n) => ({ json: n }));

// برای هر اعلان یک درخواست به مدل زبانی می‌سازد. مدل فقط «لحن و جمله‌بندی» را می‌نویسد؛
// همه‌ی واقعیت‌ها (نام، وضعیت، تاریخ، مهلت) را پورتال داده است.
const system = [
  'تو نویسنده‌ی اعلان‌های سامانه‌ی مدیریت پروژه‌ی کارشناسی دانشگاه هستی.',
  'با استفاده از «واقعیت‌ها» یک پیام کوتاه (حداکثر ۴ جمله)، رسمی و مؤدبانه به فارسی برای گیرنده بنویس.',
  'قواعد:',
  '۱. پیام را با «<نام گیرنده> گرامی،» شروع کن.',
  '۲. فقط از واقعیت‌های داده‌شده استفاده کن؛ هیچ تاریخ، مهلت، نام، عدد یا وعده‌ای از خودت اضافه نکن.',
  '۳. اگر your_actions خالی نیست، روشن بگو چه اقدامی از گیرنده انتظار می‌رود؛ اگر خالی است، بگو پیام فقط برای اطلاع است.',
  '۴. پیوند، امضا و جمله‌ی «به این پیام پاسخ ندهید» ننویس؛ سامانه خودش اضافه می‌کند.',
  'خروجی فقط متن پیام باشد، بدون عنوان و بدون توضیح اضافه.',
].join('\n');

return $input.all().map((item) => ({
  json: {
    ...item.json,
    llm_request: {
      model: $env.LLM_CHAT_MODEL,
      temperature: 0.3,
      stream: false,
      messages: [
        { role: 'system', content: system },
        { role: 'user', content: 'واقعیت‌ها:\n' + JSON.stringify(item.json.facts, null, 2) },
      ],
    },
  },
}));

// متن نهایی ایمیل: نوشته‌ی مدل زبانی (اگر سالم و کوتاه باشد) وگرنه متن ثابت پشتیبانِ پورتال،
// به‌اضافه‌ی پانویس ثابت (پیوند پورتال + «پاسخ ندهید»). پس خرابی مدل جلوی اطلاع‌رسانی را نمی‌گیرد.
const prepared = $('Build Prompt').all();

return $input.all().map((item, i) => {
  const n = prepared[i].json;
  const res = item.json || {};
  const content = res.choices && res.choices[0] && res.choices[0].message && res.choices[0].message.content;
  let text = content ? String(content).replace(/<think>[\s\S]*?<\/think>/g, '').trim() : '';
  const usable = text.length >= 20 && text.length <= 1200;
  if (!usable) text = n.fallback_body;
  return {
    json: {
      key: n.key,
      to: n.to,
      subject: n.subject,
      body: `${text}\n\n${n.footer}`,
      generated_by: usable ? 'llm' : 'template',
    },
  };
});
